// Each node: { name, client: bool, children: [...] }. A node with client:true
// is a 'use client' boundary — it and every descendant hydrate. Server Components
// (client:false) outside any boundary ship zero JS and never hydrate.
const tree = {
  name: 'Layout', client: false, children: [
    { name: 'Header', client: false, children: [
      { name: 'NavBar', client: false, children: [] },
      { name: 'SearchBox', client: true, children: [
        { name: 'SearchInput', client: false, children: [] },
        { name: 'SearchResults', client: false, children: [] }
      ] }
    ] },
    { name: 'ProductGrid', client: false, children: [
      { name: 'ProductCard', client: false, children: [
        { name: 'AddToCartButton', client: true, children: [] }
      ] }
    ] },
    { name: 'Footer', client: false, children: [] }
  ]
};
